<script lang="ts">
import { onMount } from 'svelte';
import { FolderPlus, FileText, Search, ArrowLeft, Trash2, Music, Grid2X2, List, BookOpen, Clock3, Star, Play, Tag, X, SlidersHorizontal } from 'lucide-svelte';
import * as pdfjsLib from 'pdfjs-dist';
import { db } from './db';
import type { ScoreItem } from './types';
let { onSelectScore }: { onSelectScore:(score:ScoreItem)=>void } = $props();
let scores=$state<ScoreItem[]>([]), searchQuery=$state(''), isProcessing=$state(false), selectedComposerFolder=$state<string|null>(null), viewMode=$state<'grid'|'list'>('grid'), sortMode=$state<'recent'|'title'|'composer'>('recent'), filter=$state<'all'|'favorites'|'recent'>('all'), tagFilter=$state('');
onMount(async()=>{scores=await db.scores.orderBy('addedAt').reverse().toArray();});
async function createThumbnail(file:File){const doc=await pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;const totalPages=doc.numPages;const page=await doc.getPage(1);const viewport=page.getViewport({scale:.32});const canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)return{thumbnailUrl:undefined,totalPages};await page.render({canvasContext:ctx,viewport}).promise;await doc.destroy();return{thumbnailUrl:canvas.toDataURL('image/jpeg',.72),totalPages};}
async function handleFolderSelect(e:Event){const input=e.target as HTMLInputElement;if(!input.files?.length)return;isProcessing=true;try{for(const file of Array.from(input.files)){if(!file.name.toLowerCase().endsWith('.pdf'))continue;const parts=(file.webkitRelativePath||file.name).split('/');const composer=parts.length>=2?parts[parts.length-2]:'Unknown Composer';let thumbnailUrl:string|undefined,totalPages=1;try{({thumbnailUrl,totalPages}=await createThumbnail(file));}catch(err){console.warn('Preview:',file.name,err);}const score:ScoreItem={id:`${file.name}-${file.lastModified}-${Math.random()}`,title:file.name.replace(/\.pdf$/i,''),composer,pdfBlob:file,thumbnailUrl,totalPages,addedAt:Date.now(),lastOpenedAt:0,favorite:false,tags:[],collection:composer};await db.scores.put(score);scores=[score,...scores];}}finally{isProcessing=false;input.value='';}}
async function updateScore(score:ScoreItem,patch:Partial<ScoreItem>,e?:MouseEvent){e?.stopPropagation();const next={...score,...patch};await db.scores.put(next);scores=scores.map(s=>s.id===score.id?next:s);}
async function openScore(score:ScoreItem){await updateScore(score,{lastOpenedAt:Date.now()});onSelectScore({...score,lastOpenedAt:Date.now()});}
async function toggleFavorite(score:ScoreItem,e:MouseEvent){await updateScore(score,{favorite:!score.favorite},e);}
async function deleteScore(id:string,e:MouseEvent){e.stopPropagation();await db.scores.delete(id);await db.annotations.where('scoreId').equals(id).delete();scores=scores.filter(s=>s.id!==id);}
function pages(n:number){return `${n} ${n===1?'page':'pages'}`;}
function initials(name:string){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
const filteredScores=$derived(scores.filter(s=>!selectedComposerFolder||s.composer===selectedComposerFolder).filter(s=>filter==='all'||(filter==='favorites'?!!s.favorite:!!s.lastOpenedAt)).filter(s=>{const q=searchQuery.toLowerCase().trim();const tags=(s.tags||[]).join(' ').toLowerCase();return (!q||s.title.toLowerCase().includes(q)||s.composer.toLowerCase().includes(q)||tags.includes(q))&&(!tagFilter||tags.includes(tagFilter.toLowerCase()));}).sort((a,b)=>sortMode==='title'?a.title.localeCompare(b.title):sortMode==='composer'?a.composer.localeCompare(b.composer):(b.lastOpenedAt||b.addedAt)-(a.lastOpenedAt||a.addedAt)));
const composersMap=$derived.by(()=>{const map:Record<string,ScoreItem[]>={};for(const s of scores){if((searchQuery&&!s.title.toLowerCase().includes(searchQuery.toLowerCase())&&!s.composer.toLowerCase().includes(searchQuery.toLowerCase())))continue;(map[s.composer||'Unknown Composer']||=[]).push(s);}return map;});
const allTags=$derived(Array.from(new Set(scores.flatMap(s=>s.tags||[]))).sort());
</script>
<div class="flex-1 flex flex-col p-5 sm:p-7 max-w-7xl w-full mx-auto overflow-hidden">
<header class="flex flex-col lg:flex-row lg:items-center justify-between gap-5 pb-5 border-b border-neutral-800"><div class="flex items-center gap-3 min-w-0">{#if selectedComposerFolder}<button onclick={()=>selectedComposerFolder=null} class="p-2.5 rounded-xl bg-neutral-900 border border-neutral-800 hover:bg-neutral-800"><ArrowLeft size={18}/></button>{/if}<div class="min-w-0"><div class="flex items-center gap-2"><BookOpen size={18} class="text-blue-400"/><h1 class="text-2xl sm:text-3xl font-semibold tracking-tight truncate">{selectedComposerFolder||'Music Library'}</h1></div><p class="text-sm text-neutral-500 mt-1">{selectedComposerFolder?`${filteredScores.length} scores`:'A focused home for your sheet music'}</p></div></div><label class="inline-flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-500 text-white px-4 py-2.5 rounded-xl cursor-pointer font-medium"><FolderPlus size={18}/>{isProcessing?'Importing…':'Import folder'}<input type="file" webkitdirectory directory multiple accept="application/pdf" onchange={handleFolderSelect} disabled={isProcessing} class="hidden"/></label></header>
<div class="flex flex-wrap gap-2 my-5"><div class="relative flex-1 min-w-52"><Search size={17} class="absolute left-3.5 top-1/2 -translate-y-1/2 text-neutral-500"/><input bind:value={searchQuery} placeholder="Search titles, composers, or tags…" class="w-full bg-neutral-900 border border-neutral-800 rounded-xl pl-10 pr-4 py-3 text-sm outline-none focus:border-blue-500"/></div><div class="flex bg-neutral-900 border border-neutral-800 rounded-xl p-1"><button onclick={()=>filter='all'} class="px-3 py-2 rounded-lg text-xs {filter==='all'?'bg-neutral-800 text-white':'text-neutral-500'}">All</button><button onclick={()=>filter='favorites'} class="px-3 py-2 rounded-lg text-xs {filter==='favorites'?'bg-neutral-800 text-white':'text-neutral-500'}">Favorites</button><button onclick={()=>filter='recent'} class="px-3 py-2 rounded-lg text-xs {filter==='recent'?'bg-neutral-800 text-white':'text-neutral-500'}">Recent</button></div>{#if selectedComposerFolder}<select bind:value={sortMode} class="bg-neutral-900 border border-neutral-800 rounded-xl px-3 text-sm text-neutral-300"><option value="recent">Recent</option><option value="title">Title</option><option value="composer">Composer</option></select><div class="flex bg-neutral-900 border border-neutral-800 rounded-xl p-1"><button onclick={()=>viewMode='grid'} class="p-2 rounded-lg {viewMode==='grid'?'bg-neutral-800 text-white':'text-neutral-500'}"><Grid2X2 size={16}/></button><button onclick={()=>viewMode='list'} class="p-2 rounded-lg {viewMode==='list'?'bg-neutral-800 text-white':'text-neutral-500'}"><List size={16}/></button></div>{/if}</div>
{#if allTags.length}<div class="flex gap-2 overflow-x-auto pb-1"><Tag size={14} class="text-neutral-600 mt-1.5 shrink-0"/>{#each allTags as tag}<button onclick={()=>tagFilter=tagFilter===tag?'':tag} class="px-2.5 py-1 rounded-full text-[11px] border {tagFilter===tag?'bg-blue-600/20 border-blue-500 text-blue-300':'bg-neutral-900 border-neutral-800 text-neutral-500'}">{tag}</button>{/each}{#if tagFilter}<button onclick={()=>tagFilter=''} class="text-xs text-neutral-500"><X size={14}/></button>{/if}</div>{/if}
<div class="flex-1 overflow-y-auto pr-1">
{#if scores.length===0}<div class="h-72 flex flex-col items-center justify-center border border-dashed border-neutral-800 rounded-3xl text-neutral-500 gap-3"><Music size={38}/><p>No scores imported yet.</p><p class="text-xs text-neutral-600">Import a folder of PDFs to begin.</p></div>
{:else if !selectedComposerFolder}<div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">{#each Object.entries(composersMap).sort(([a],[b])=>a.localeCompare(b)) as [composer,items]}<button onclick={()=>selectedComposerFolder=composer} class="group text-left relative rounded-3xl border border-neutral-800 bg-neutral-900/70 hover:bg-neutral-900 hover:border-neutral-700 overflow-hidden transition"><div class="h-36 relative overflow-hidden bg-neutral-950"><div class="absolute -right-5 -top-10 w-40 h-40 rounded-full bg-blue-500/5"></div><div class="absolute inset-x-8 bottom-[-28px] h-32 flex items-end justify-center"><div class="w-24 h-32 bg-neutral-800 border border-neutral-700 rounded-t-lg -rotate-6 shadow-2xl"></div><div class="w-24 h-34 bg-neutral-700 border border-neutral-600 rounded-t-lg rotate-0 shadow-2xl flex flex-col items-center justify-center gap-2"><Music size={22} class="text-neutral-400"/><span class="text-[10px] text-neutral-500">{items.length} scores</span></div><div class="w-24 h-32 bg-neutral-800 border border-neutral-700 rounded-t-lg rotate-6 shadow-2xl"></div></div><div class="absolute top-4 left-4 w-11 h-11 rounded-2xl bg-neutral-900 border border-neutral-700 flex items-center justify-center font-semibold text-neutral-300">{initials(composer)}</div></div><div class="p-5 flex items-center justify-between gap-4"><div class="min-w-0"><h2 class="font-semibold text-neutral-100 truncate">{composer}</h2><p class="text-xs text-neutral-500 mt-1">{items.length} {items.length===1?'score':'scores'} · Open collection</p></div><div class="w-9 h-9 rounded-xl bg-neutral-800 flex items-center justify-center text-neutral-500 group-hover:text-blue-300"><ArrowLeft size={16} class="rotate-180"/></div></div></button>{/each}</div>
{:else if filteredScores.length===0}<div class="h-56 flex items-center justify-center text-neutral-500">No scores match your filters.</div>
{:else if viewMode==='list'}<div class="rounded-2xl border border-neutral-800 overflow-hidden divide-y divide-neutral-800 bg-neutral-900/60">{#each filteredScores as score}<div role="button" tabindex="0" onclick={()=>openScore(score)} class="flex items-center gap-4 p-3.5 text-left hover:bg-neutral-800/70 transition group cursor-pointer"><div class="w-12 h-16 rounded-lg bg-neutral-950 overflow-hidden border border-neutral-800 shrink-0 flex items-center justify-center">{#if score.thumbnailUrl}<img src={score.thumbnailUrl} alt="" class="w-full h-full object-cover object-top"/>{:else}<FileText size={23} class="text-neutral-600"/>{/if}</div><div class="min-w-0 flex-1"><div class="text-sm font-semibold text-neutral-200 truncate">{score.title}</div><div class="flex items-center gap-3 text-xs text-neutral-500 mt-1"><span>{pages(score.totalPages)}</span>{#if score.lastOpenedAt}<span class="inline-flex items-center gap-1"><Clock3 size={12}/>Recent</span>{/if}</div></div><button onclick={e=>toggleFavorite(score,e)} class="p-2 text-neutral-500 hover:text-yellow-400"><Star size={16} fill={score.favorite?'currentColor':'none'} class={score.favorite?'text-yellow-400':''}/></button><button onclick={e=>deleteScore(score.id,e)} class="p-2 text-neutral-500 hover:text-red-400"><Trash2 size={16}/></button></div>{/each}</div>
{:else}<div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">{#each filteredScores as score}<div class="group relative rounded-2xl bg-neutral-900 border border-neutral-800 hover:border-neutral-700 overflow-hidden transition"><button onclick={()=>openScore(score)} class="w-full text-left"><div class="aspect-[3/4] bg-neutral-950 p-2 flex items-center justify-center border-b border-neutral-800">{#if score.thumbnailUrl}<img src={score.thumbnailUrl} alt="" class="max-w-full max-h-full object-contain shadow-lg"/>{:else}<FileText size={32} class="text-neutral-700"/>{/if}</div><div class="p-3.5"><h3 class="text-sm font-medium text-neutral-100 truncate">{score.title}</h3><div class="text-xs text-neutral-500 mt-1">{pages(score.totalPages)}</div></div></button><div class="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition"><button onclick={e=>toggleFavorite(score,e)} class="p-2 rounded-lg bg-neutral-900/90 border border-neutral-700 text-neutral-400 hover:text-yellow-400"><Star size={14} fill={score.favorite?'currentColor':'none'}/></button><button onclick={e=>deleteScore(score.id,e)} class="p-2 rounded-lg bg-neutral-900/90 border border-neutral-700 text-neutral-400 hover:text-red-400"><Trash2 size={14}/></button></div></div>{/each}</div>{/if}</div></div>
